'use client';
import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import { ArrowLeft, Cloud, ExternalLink, Folder, FolderPlus } from 'lucide-react';
import { useToast } from '@/components/ui/Toast';

export default function VendorDrivePage() {
  const { id } = useParams();
  const showToast = useToast();
  const [project,setProject]=useState(null); const [folders,setFolders]=useState([]); const [loading,setLoading]=useState(true); const [busy,setBusy]=useState(false);
  async function load(){ setLoading(true); try { const [pr,fr]=await Promise.all([fetch(`/api/projects/${id}`),fetch(`/api/projects/${id}/drive/folders`)]); const pd=await pr.json(); const fd=await fr.json(); if(!pr.ok) throw new Error(pd.error||'Unable to load project.'); if(!fr.ok) throw new Error(fd.error||'Unable to load Drive folders.'); setProject(pd.project); setFolders(fd.folders||[]); } catch(e){showToast(e.message,'error');} finally{setLoading(false);} }
  useEffect(()=>{load();},[id]);
  async function create(parentId){ const name=window.prompt('New folder name'); if(!name?.trim()||busy)return; setBusy(true); try{const res=await fetch(`/api/projects/${id}/drive/folders`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.trim(),parentId})});const data=await res.json();if(!res.ok)throw new Error(data.error||'Unable to create folder.');await load();showToast(`Folder “${data.folder.name}” created.`,'success');}catch(e){showToast(e.message,'error');}finally{setBusy(false);}}
  if(loading)return <div className="text-secondary">Loading Drive workspace…</div>;
  return <div className="space-y-6"><a href={`/vendor/projects/${id}`} className="text-sm text-secondary inline-flex items-center gap-1.5"><ArrowLeft size={14}/> Back to project</a><div className="rounded-[26px] bg-primary text-white p-7 sm:p-9"><div className="flex items-start justify-between gap-4 flex-wrap"><div><span className="text-gold text-[10px] uppercase tracking-[.2em] font-semibold">Drive workspace</span><h1 className="font-head text-3xl mt-2">{project?.drive?.folderName||project?.projectCode}</h1><p className="text-sm text-white/50 mt-2">Create folders and subfolders for RAW and EDITED uploads.</p></div>{project?.drive?.projectFolderUrl&&<a href={project.drive.projectFolderUrl} target="_blank" rel="noreferrer" className="btn btn-gold btn-sm"><Cloud size={14}/> Open in Google Drive</a>}</div></div><div className="panel"><div className="flex items-center justify-between gap-3 flex-wrap mb-5"><div><h2 className="font-head text-xl">Folder structure</h2><p className="text-xs text-secondary mt-1">New folders inherit your project access automatically.</p></div><button onClick={()=>create(project?.drive?.projectFolderId)} disabled={busy} className="btn btn-outline btn-sm"><FolderPlus size={14}/> New folder</button></div><div className="grid gap-2">{project?.drive?.rawFolderId&&<div className="rounded-xl border border-border p-4 flex items-center justify-between gap-3"><div><b className="text-sm">RAW</b><p className="text-xs text-secondary">Original/source files</p></div><div className="flex gap-2"><button onClick={()=>create(project.drive.rawFolderId)} className="btn btn-outline btn-sm"><FolderPlus size={13}/> Subfolder</button><a href={project.drive.rawFolderUrl} target="_blank" rel="noreferrer" className="btn btn-outline btn-sm"><ExternalLink size={13}/></a></div></div>}{project?.drive?.editedFolderId&&<div className="rounded-xl border border-border p-4 flex items-center justify-between gap-3"><div><b className="text-sm">EDITED</b><p className="text-xs text-secondary">Final photographs and videos</p></div><div className="flex gap-2"><button onClick={()=>create(project.drive.editedFolderId)} className="btn btn-outline btn-sm"><FolderPlus size={13}/> Subfolder</button><a href={project.drive.editedFolderUrl} target="_blank" rel="noreferrer" className="btn btn-outline btn-sm"><ExternalLink size={13}/></a></div></div>}{folders.filter(f=>!['RAW','EDITED'].includes(f.name)).map(f=><div key={f.id} className="rounded-xl border border-border p-3 pl-4 flex items-center justify-between gap-3" style={{marginLeft:Math.min(f.depth,5)*20}}><div className="flex items-center gap-2"><Folder size={16} className="text-gold"/><div><b className="text-xs">{f.name}</b><p className="text-[10px] text-secondary">{f.path}</p></div></div><button onClick={()=>create(f.id)} className="btn btn-outline btn-sm"><FolderPlus size={13}/> Subfolder</button></div>)}</div></div></div>;
}
